class Volume(ABC):
    @abstractmethod
    def volume(self):
        pass

class VolumeCalculator:
    def __init__(self, shapes=[]):
        self.shapes = shapes

    def sum(self):
        total_volume = 0
        for shape in self.shapes:
            if isinstance(shape, Volume):
                total_volume += shape.volume()
            else:
                raise Exception("Invalid Shape: Shape does not implement Volume interface")
        return total_volume

